import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Vector3,
  Euler,
  Color
} from 'three';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} imageUrl
 * @property {Array<number>} position
 * @property {Array<number>} rotation
 * @property {Array<number>} scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>THREE.Texture} textureLoader
 * @property {{[key:string]:(obj:THREE.Object3D,params:any)=>void}} primitives
 * @property {{emit?: (event:string)=>void}} [events]
 */

/**
 * Creates a textured plane thumbnail card.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const {
    imageUrl,
    position = [0, 0, 0],
    rotation = [0, 0, 0],
    scale = [1, 1, 1]
  } = config;

  // Load texture (cached)
  const tex = ctx.textureLoader(imageUrl);

  // Plane size derived from atlas region (512 × 320 → 1.6 × 1)
  const width = 512 / 320; // 1.6
  const height = 1;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    map: texture(tex)
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(...position);
  mesh.rotation.set(...rotation);
  mesh.scale.set(...scale);

  // Store base Y for hover animation
  const baseY = mesh.position.y;

  // Handlers container
  mesh.userData.handlers = {};

  // Hover lift (rise‑in) – subtle 0.15 scene units
  mesh.userData.handlers.hover = () => {
    if (mesh.userData._hoverTween) mesh.userData._hoverTween.kill();
    mesh.userData._hoverTween = gsap.to(mesh.position, {
      y: baseY + 0.15,
      duration: 0.15,
      ease: 'power3.out'
    });
  };

  // Optional mouseout to restore position (if the system calls it)
  mesh.userData.handlers.hoverOut = () => {
    if (mesh.userData._hoverTween) mesh.userData._hoverTween.kill();
    mesh.userData._hoverTween = gsap.to(mesh.position, {
      y: baseY,
      duration: 0.15,
      ease: 'power3.out'
    });
  };

  // Click emits navigation event
  mesh.userData.handlers.click = () => {
    if (ctx.events && typeof ctx.events.emit === 'function') {
      ctx.events.emit('hub-journal.select');
    }
  };

  // Cleanup routine
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (tex && typeof tex.dispose === 'function') tex.dispose();
    if (mesh.userData._hoverTween) mesh.userData._hoverTween.kill();
    mesh.userData.handlers = null;
  };

  return mesh;
}
